program.compute:
cache_rows = read('/input/options')
from itertools import combinations
result = []
min_c = goal['min_count']
max_c = goal['max_count']
sum_bounds = goal['sum_bounds']
unique_fields = goal['unique']
order_by = goal['order_by']

# Filter function to check unique owners

def unique_owners(ids):
    owners = []
    for id_ in ids:
        for opt in cache_rows:
            if opt['id'] == id_:
                owners.append(opt['owner'])
                break
    return len(set(owners)) == len(owners)

# Check sum bounds for quality and cost

def sum_bounds_ok(ids):
    quality_sum = 0
    cost_sum = 0
    for id_ in ids:
        for opt in cache_rows:
            if opt['id'] == id_:
                quality_sum += opt['quality']
                cost_sum += opt['cost']
                break
    if 'quality' in sum_bounds:
        if 'min' in sum_bounds['quality'] and quality_sum < sum_bounds['quality']['min']:
            return False
        if 'max' in sum_bounds['quality'] and quality_sum > sum_bounds['quality']['max']:
            return False
    if 'cost' in sum_bounds:
        if 'min' in sum_bounds['cost'] and cost_sum < sum_bounds['cost']['min']:
            return False
        if 'max' in sum_bounds['cost'] and cost_sum > sum_bounds['cost']['max']:
            return False
    return True

# Check unique owners

def unique_ok(ids):
    if 'owner' in unique_fields:
        return unique_owners(ids)
    return True

# Check no conflicts

def no_conflicts_ok(ids):
    if not goal['no_conflicts']:
        return True
    # Build set for quick lookup
    id_set = set(ids)
    for id_ in ids:
        for opt in cache_rows:
            if opt['id'] == id_:
                for conflict in opt['conflicts']:
                    if conflict in id_set:
                        return False
    return True

# Check closed dependencies

def closed_dependencies_ok(ids):
    if not goal['closed_dependencies']:
        return True
    id_set = set(ids)
    for id_ in ids:
        for opt in cache_rows:
            if opt['id'] == id_:
                for req in opt['requires']:
                    if req not in id_set:
                        return False
    return True

# Check cover fields

def cover_ok(ids):
    cover = goal['cover']
    if not cover:
        return True
    # For each field in cover, check if all required values are covered
    for field in cover:
        required_values = cover[field]
        values_found = []
        for id_ in ids:
            for opt in cache_rows:
                if opt['id'] == id_:
                    val = opt.get(field)
                    if isinstance(val, list):
                        values_found += val
                    else:
                        values_found.append(val)
        for val in required_values:
            if val not in values_found:
                return False
    return True

# Check order by

def order_ok(ids):
    # Sort by order_by fields ascending
    def keyfunc(id_):
        for opt in cache_rows:
            if opt['id'] == id_:
                return tuple(opt[field] for field in order_by)
        return ()
    sorted_ids = sorted(ids, key=keyfunc)
    return ids == sorted_ids

# Validate candidate

def valid_candidate(ids):
    if len(ids) < min_c or len(ids) > max_c:
        return False
    if not unique_ok(ids):
        return False
    if not no_conflicts_ok(ids):
        return False
    if not closed_dependencies_ok(ids):
        return False
    if not cover_ok(ids):
        return False
    if not sum_bounds_ok(ids):
        return False
    if not order_ok(ids):
        return False
    return True

# Try combinations from min_c to max_c

found = False
for c in range(min_c, max_c+1):
    for comb in combinations(cache_rows, c):
        ids = [opt['id'] for opt in comb]
        if valid_candidate(ids):
            result = ids
            found = True
            break
    if found:
        break

if not found:
    result = []

program.effects:
existing = read('/output/selection')
if existing is not None and valid(existing):
    # reuse existing
    send('report','team',existing)
else:
    if result and valid(result):
        # write, send, delete
        write_path = '/output/selection'
        write(write_path,result)
        send('report','team',result)
    else:
        # no valid selection found
        result = []
if exists('/tmp/cache'):
    delete('/tmp/cache')

status('report')

